param([switch]$KeepContainer)$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '\..\..'));$c='nello_clinical_attachments_test'
$m=@('20260813024000_c6_canonical_document_artifacts.sql','20260813025000_c6_document_signatures_authenticity.sql','20260813025500_c6_authenticity_rate_limit.sql','20260813025600_c6_document_foreign_key_indexes.sql')|%{Join-Path $root "supabase\migrations\$_"};$t=Join-Path $root 'supabase\tests\c6_document_artifacts_matrix.sql'
try{& (Join-Path $PSScriptRoot 'verify-c6-document-composition.ps1') -KeepContainer;if($LASTEXITCODE -ne 0){throw 'C6.3 failed'};for($i=0;$i -lt $m.Count;$i++){docker cp $m[$i] "${c}:/tmp/c6-art-$i.sql"|Out-Null;docker exec -e PGPASSWORD=postgres $c psql --single-transaction -v ON_ERROR_STOP=1 -U supabase_admin -d postgres -f "/tmp/c6-art-$i.sql"|Out-Null;if($LASTEXITCODE -ne 0){throw "C6 artifact migration $i failed"}};docker cp $t "${c}:/tmp/c6-art-matrix.sql"|Out-Null;docker exec -e PGPASSWORD=postgres $c psql -v ON_ERROR_STOP=1 -U supabase_admin -d postgres -f /tmp/c6-art-matrix.sql;if($LASTEXITCODE -ne 0){throw 'C6.4/C6.5 matrix failed'};Write-Output 'C6.4/C6.5 canonical artifact and authenticity matrix approved.'}finally{if(-not $KeepContainer){docker rm -f $c 2>$null|Out-Null}}
